function offsetDate(days){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function getData(){try{return {...initial,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch{return structuredClone(initial)}}
let data=getData();
let backendUser=null;
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Could not connect to your account.');return body}
async function persistAction(payload){if(!backendUser)return;try{await api('/api/data',{method:'POST',body:JSON.stringify(payload)})}catch(e){toast(e.message)}}
async function refreshBackend(){try{const auth=await api('/api/auth');if(!auth.user)return;backendUser=auth.user;const remote=await api('/api/data');data.transactions=(remote.transactions||[]).map(t=>({...t,amount:Number(t.amount),date:String(t.date).slice(0,10),type:t.type||'expense'}));data.budgets=(remote.budgets||[]).map(b=>({name:b.category,icon:categoryIcon(b.category),limit:Number(b.limit),spent:data.transactions.filter(t=>t.category===b.category&&t.type==='expense'&&t.date.slice(0,7)===new Date().toISOString().slice(0,7)).reduce((a,t)=>a+t.amount,0),color:'blue'}));data.products=(remote.products||[]).map(p=>({id:p.id,name:p.name,category:p.category,price:Number(p.price),saved:Number(p.saved),icon:'✦',tone:'blue',priority:p.priority}));data.accounts=(remote.accounts||[]).map(a=>({id:a.id,name:a.name,type:a.type,balance:Number(a.balance),currency:a.currency,icon:'▤'}));save();const btn=document.getElementById('account-button');btn.textContent=backendUser.name.split(' ')[0];btn.classList.add('signed-in');const banner=document.getElementById('sync-banner');banner.classList.add('connected');banner.innerHTML='<span class="sync-indicator"></span><span><strong>Synced securely</strong> · Your account is connected.</span><button id="sync-signin" type="button">Manage account ↗</button>';document.getElementById('sync-signin').onclick=()=>setPage('settings');if(currentPage==='dashboard')document.getElementById('page-title').innerHTML='Good morning, '+esc(backendUser.name.split(' ')[0])+' <span class="wave">✦</span>';render()}catch{/* Demo mode remains available until backend credentials are configured. */}}
const view=document.getElementById('page-view');
let currentPage='dashboard';
let transactionType='expense';
let toastTimer;
const symbols={PHP:'₱',USD:'$',EUR:'€',GBP:'£'};
const currency=()=>symbols[data.currency]||'₱';
const money=(n,decimals=false)=>currency()+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:decimals?2:0,maximumFractionDigits:decimals?2:0});
const save=()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(data));
const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=(iso)=>{const d=new Date(iso+'T12:00:00');return d.toLocaleDateString('en-PH',{month:'short',day:'numeric'})};
const categoryTone=(cat)=>({'Food & dining':'food','Shopping':'shop','Transport':'transport','Housing':'home','Salary':'salary','Health':'health','Entertainment':'fun'}[cat]||'shop');
const categoryIcon=(cat)=>({'Food & dining':'☕','Shopping':'◈','Transport':'↗','Housing':'⌂','Salary':'↗','Health':'✚','Entertainment':'♫'}[cat]||'✧');
function currentMonthTransactions(){const m=today.getMonth(),y=today.getFullYear();return data.transactions.filter(t=>{const d=new Date(t.date+'T12:00:00');return d.getMonth()===m&&d.getFullYear()===y})}
function sums(){const tx=currentMonthTransactions();return {income:tx.filter(t=>t.type==='income').reduce((a,t)=>a+Number(t.amount),0),spent:tx.filter(t=>t.type==='expense').reduce((a,t)=>a+Number(t.amount),0)}}
function setPage(page){currentPage=page;document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumb-current').textContent=({dashboard:'Dashboard',transactions:'Transactions',budgets:'Budgets',products:'Product list',networth:'Net worth',activity:'Access activity',settings:'Settings'})[page]||'Dashboard';document.getElementById('page-title').innerHTML=page==='dashboard'?'Good morning, Jamie <span class="wave">✦</span>':({transactions:'Transactions',budgets:'Your budgets',products:'Your product list',networth:'Net worth overview',activity:'Access activity',settings:'Your settings'})[page]||'Dashboard';document.getElementById('page-subtitle').textContent=({dashboard:'Here’s what’s happening with your money today.',transactions:'Every peso, accounted for. Review your recent money moves.',budgets:'Make room for the things that matter.',products:'Plan ahead for the things you’re working toward.',networth:'See your full financial picture, all in one place.',activity:'Keep an eye on sign-ins and changes to your account.',settings:'Make BlueLedger feel like yours.'})[page]||'';render();document.getElementById('sidebar').classList.remove('open')}
function render(){save(); if(currentPage==='dashboard')renderDashboard();if(currentPage==='transactions')renderTransactions();if(currentPage==='budgets')renderBudgets();if(currentPage==='products')renderProducts();if(currentPage==='networth')renderNetworth();if(currentPage==='activity')renderActivity();if(currentPage==='settings')renderSettings()}
function metrics(){const s=sums();const assets=data.accounts.filter(a=>a.balance>0).reduce((a,x)=>a+x.balance,0),liabilities=Math.abs(data.accounts.filter(a=>a.balance<0).reduce((a,x)=>a+x.balance,0));return {s,assets,liabilities,net:assets-liabilities}}
function transactionRows(list,limit=5){if(!list.length)return `<tr><td colspan="5"><div class="empty-state"><div>✧</div><strong>No transactions yet</strong><p>Add your first transaction to see your money activity here.</p><button class="button button-primary" onclick="openModal()">Add transaction</button></div></td></tr>`;return list.slice(0,limit).map(t=>`<tr><td class="tx-name"><span class="tx-icon ${categoryTone(t.category)}">${categoryIcon(t.category)}</span>${esc(t.description)}</td><td>${esc(t.category)}</td><td class="tx-muted">${dateLabel(t.date)}</td><td><span class="pill">${esc(t.account)}</span></td><td class="tx-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td></tr>`).join('')}
function budgetRows(){return data.budgets.slice(0,4).map(b=>{const pct=Math.min(100,Math.round(b.spent/b.limit*100));const color=pct>85?'warning':pct<60?'success':'';return `<div class="budget-row"><div class="budget-line"><span class="budget-name"><i>${b.icon}</i>${esc(b.name)}</span><span class="budget-amount"><strong>${money(b.spent)}</strong> / ${money(b.limit)}</span></div><div class="progress-track"><div class="progress-fill ${color}" style="width:${pct}%"></div></div><div class="budget-caption">${money(Math.max(0,b.limit-b.spent))} left this month</div></div>`}).join('')}
function renderDashboard(){const {s,net}=metrics();document.getElementById('budget-nav-count').textContent=data.budgets.length;const tx=[...data.transactions].sort((a,b)=>b.date.localeCompare(a.date));const sumBy={};currentMonthTransactions().filter(t=>t.type==='expense').forEach(t=>sumBy[t.category]=(sumBy[t.category]||0)+Number(t.amount));const catEntries=Object.entries(sumBy).sort((a,b)=>b[1]-a[1]);const top=catEntries.slice(0,4);const total=catEntries.reduce((a,x)=>a+x[1],0)||1;const colors=['#3e73e8','#8fb1ff','#62c9aa','#f4b36e'];
view.innerHTML=`<div class="grid top-metrics"><article class="card metric-card primary-metric"><div class="metric-label">Total balance <span class="info-dot" title="Balances across your accounts">i</span></div><div class="metric-value">${money(net)}</div><div class="metric-foot"><span class="metric-trend">↗ 4.8%</span> up from last month</div><div class="metric-icon">◈</div></article><article class="card metric-card"><div class="metric-label">Income this month</div><div class="metric-value">${money(s.income)}</div><div class="metric-foot"><span class="metric-trend">↗ 12.4%</span> vs. last month</div><div class="metric-icon">↗</div></article><article class="card metric-card"><div class="metric-label">Spent this month</div><div class="metric-value">${money(s.spent)}</div><div class="metric-foot"><span class="metric-trend">↘ 6.2%</span> vs. last month</div><div class="metric-icon">↘</div></article><article class="card metric-card"><div class="metric-label">Savings rate</div><div class="metric-value">${s.income?Math.max(0,Math.round((s.income-s.spent)/s.income*100)):0}%</div><div class="metric-foot">Of your take-home income</div><div class="metric-icon">◎</div></article></div>
<div class="grid middle-grid"><article class="card spending-card"><div class="card-head"><div><h2 class="card-title">Income vs. spending</h2><p class="card-hint">A clearer look at your money flow</p></div><select class="select-small" id="chart-period"><option>This month</option><option>Last month</option><option>Last 6 months</option></select></div><div class="chart-wrap"><svg class="spending-svg" viewBox="0 0 660 175" preserveAspectRatio="none" role="img" aria-label="Monthly income and spending chart"><defs><linearGradient id="areaGrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#5b87f2" stop-opacity=".18"/><stop offset="100%" stop-color="#5b87f2" stop-opacity="0"/></linearGradient></defs><path class="grid-line" d="M40 25H650M40 65H650M40 105H650M40 145H650"/><text class="axis-label" x="4" y="28">₱60k</text><text class="axis-label" x="4" y="68">₱40k</text><text class="axis-label" x="4" y="108">₱20k</text><text class="axis-label" x="12" y="148">₱0</text><path class="area-fill" d="M40 60 C90 78 105 55 143 66 S201 45 245 58 S302 40 349 51 S412 67 451 47 S520 43 560 31 S620 50 650 34 L650 145 L40 145Z"/><path class="area-line" d="M40 60 C90 78 105 55 143 66 S201 45 245 58 S302 40 349 51 S412 67 451 47 S520 43 560 31 S620 50 650 34"/><path class="area-line-two" d="M40 119 C90 109 110 122 143 106 S206 120 245 103 S300 119 349 100 S408 108 451 95 S518 111 560 89 S620 102 650 83"/><text class="axis-label" x="40" y="168">Oct 1</text><text class="axis-label" x="190" y="168">Oct 7</text><text class="axis-label" x="345" y="168">Oct 14</text><text class="axis-label" x="500" y="168">Oct 21</text><text class="axis-label" x="620" y="168">Oct 31</text></svg></div><div class="chart-legend"><span><i class="legend-dot"></i>Income</span><span><i class="legend-dot light"></i>Spending</span><span class="spending-summary">Net this month <strong>${money(s.income-s.spent)}</strong></span></div></article>
<article class="card category-card"><div class="card-head"><div><h2 class="card-title">Where it goes</h2><p class="card-hint">Spending by category</p></div><button class="head-link" data-page="transactions">Details ↗</button></div><div class="donut-area"><div class="donut" style="background:conic-gradient(${top.map((e,i)=>`${colors[i]} ${top.slice(0,i).reduce((a,x)=>a+x[1]/total*100,0)}% ${top.slice(0,i+1).reduce((a,x)=>a+x[1]/total*100,0)}%`).join(',')||'#e3e9f1 0 100%'})"></div><div class="donut-center"><strong>${money(total)}</strong><span>total spent</span></div></div><div class="category-legend">${top.length?top.map((e,i)=>`<div class="legend-row"><i class="legend-dot" style="background:${colors[i]}"></i>${esc(e[0])}<strong>${total?Math.round(e[1]/total*100):0}%</strong></div>`).join(''):'<div class="legend-row">No spending yet</div>'}</div></article></div>
<div class="grid bottom-grid"><article class="card transactions-card"><div class="card-head"><div><h2 class="card-title">Recent transactions</h2><p class="card-hint">Your latest money moves</p></div><button class="head-link" data-page="transactions">View all ↗</button></div><div class="table-wrap"><table class="transaction-table"><thead><tr><th>DESCRIPTION</th><th>CATEGORY</th><th>DATE</th><th>ACCOUNT</th><th>AMOUNT</th></tr></thead><tbody>${transactionRows(tx,5)}</tbody></table></div></article><article class="card budget-card"><div class="card-head"><div><h2 class="card-title">Monthly budgets</h2><p class="card-hint">Stay on track without the stress</p></div><button class="head-link" data-page="budgets">See all ↗</button></div><div class="budget-list">${budgetRows()||'<div class="empty-state"><strong>No budgets yet</strong><p>Create a budget to guide your spending.</p></div>'}</div><div class="budget-footer"><span>Overall budget used</span><strong>${Math.round(data.budgets.reduce((a,b)=>a+b.spent,0)/(data.budgets.reduce((a,b)=>a+b.limit,0)||1)*100)}%</strong></div></article></div>`;bindPageButtons()}
function renderTransactions(){const sorted=[...data.transactions].sort((a,b)=>b.date.localeCompare(a.date));view.innerHTML=`<div class="card table-card"><div class="card-head"><div><h2 class="card-title">All transactions</h2><p class="card-hint">${data.transactions.length} records · your personal ledger</p></div><div class="toolbar"><select id="transaction-filter" class="filter-chip"><option value="all">All types</option><option value="expense">Expenses</option><option value="income">Income</option></select><button class="button button-primary" onclick="openModal()">+ Add transaction</button></div></div><div class="table-wrap"><table class="full-table"><thead><tr><th>DESCRIPTION</th><th>DATE</th><th>CATEGORY</th><th>ACCOUNT</th><th>TYPE</th><th>AMOUNT</th></tr></thead><tbody id="all-transactions">${sorted.map(t=>`<tr><td>${esc(t.description)}</td><td>${dateLabel(t.date)}</td><td>${esc(t.category)}</td><td>${esc(t.account)}</td><td><span class="pill">${t.type}</span></td><td class="tx-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="tx-muted">No transactions yet.</td></tr>'}</tbody></table></div></div><div class="page-section"><div class="card" style="padding:15px 18px;display:flex;align-items:center;justify-content:space-between"><div><strong style="font:700 11px Manrope">Your money, your rules.</strong><div style="font-size:9px;color:#919daf;margin-top:4px">Filter, export, or add a transaction any time.</div></div><button class="button" id="transaction-export">↓ Export CSV</button></div></div>`;document.getElementById('transaction-filter').onchange=e=>{document.querySelectorAll('#all-transactions tr').forEach(row=>row.style.display=e.target.value==='all'||row.children[4]?.textContent.trim()===e.target.value?'':'none')};document.getElementById('transaction-export').onclick=exportCsv}
function renderBudgets(){const total=data.budgets.reduce((a,b)=>a+b.limit,0),spent=data.budgets.reduce((a,b)=>a+b.spent,0);view.innerHTML=`<div class="grid top-metrics"><article class="card metric-card primary-metric"><div class="metric-label">Total planned</div><div class="metric-value">${money(total)}</div><div class="metric-foot">Across ${data.budgets.length} categories</div></article><article class="card metric-card"><div class="metric-label">Spent so far</div><div class="metric-value">${money(spent)}</div><div class="metric-foot">${Math.round(spent/(total||1)*100)}% of your monthly plan</div></article><article class="card metric-card"><div class="metric-label">Still available</div><div class="metric-value">${money(Math.max(0,total-spent))}</div><div class="metric-foot">A little breathing room</div></article><article class="card metric-card"><div class="metric-label">Categories</div><div class="metric-value">${data.budgets.length}</div><div class="metric-foot">Active this month</div></article></div><div class="subhead"><div><h2>Monthly categories</h2><p>Personalize your limits as life changes.</p></div><button class="button button-primary" id="add-budget">+ New budget</button></div><div class="grid budget-cards">${data.budgets.map(b=>{const pct=Math.min(100,Math.round(b.spent/b.limit*100));return `<article class="card budget-large"><div style="display:flex;align-items:center;gap:9px"><span class="category-badge">${b.icon}</span><div><div class="card-title">${esc(b.name)}</div><div class="card-hint">Monthly limit</div></div></div><div class="budget-line"><span class="big-budget">${money(b.spent)}</span><span class="budget-amount">of <strong>${money(b.limit)}</strong></span></div><div class="progress-track"><div class="progress-fill ${pct>85?'warning':pct<60?'success':''}" style="width:${pct}%"></div></div><div class="budget-caption">${money(Math.max(0,b.limit-b.spent))} remaining · ${pct}% used</div></article>`}).join('')||'<div class="card empty-state"><strong>No budgets yet</strong><p>Create a budget to get started.</p></div>'}</div>`;const btn=document.getElementById('add-budget');btn.onclick=()=>{const name=prompt('Budget category name?');if(!name)return;const limit=Number(prompt('Monthly limit amount?'));if(!limit)return;data.budgets.push({name,icon:'✦',limit,spent:0,color:'blue'});persistAction({action:'add-budget',category:name,limit});render();toast('Budget created')};}
function renderProducts(){view.innerHTML=`<div class="grid top-metrics"><article class="card metric-card primary-metric"><div class="metric-label">Total goal value</div><div class="metric-value">${money(data.products.reduce((a,p)=>a+p.price,0))}</div><div class="metric-foot">Across ${data.products.length} goals</div></article><article class="card metric-card"><div class="metric-label">Already saved</div><div class="metric-value">${money(data.products.reduce((a,p)=>a+p.saved,0))}</div><div class="metric-foot">You’re making progress</div></article><article class="card metric-card"><div class="metric-label">Left to save</div><div class="metric-value">${money(data.products.reduce((a,p)=>a+Math.max(0,p.price-p.saved),0))}</div><div class="metric-foot">One step at a time</div></article><article class="card metric-card"><div class="metric-label">Products & goals</div><div class="metric-value">${data.products.length}</div><div class="metric-foot">On your wish list</div></article></div><div class="subhead"><div><h2>Things you’re saving for</h2><p>See the full cost before it sneaks into your day-to-day spending.</p></div><button class="button button-primary" id="add-product">+ Add a goal</button></div><div class="grid products-grid">${data.products.map(p=>`<article class="card product-card"><div class="product-top"><div class="product-art ${p.tone}">${p.icon}</div><button class="more-button product-remove" data-id="${p.id}" title="Remove goal">···</button></div><div class="product-meta"><h3>${esc(p.name)}</h3><p>${esc(p.category)}</p></div><div class="product-price">${money(p.price)} <small>goal</small></div><div class="progress-track" style="margin-top:9px"><div class="progress-fill success" style="width:${Math.min(100,Math.round(p.saved/p.price*100))}%"></div></div><div class="product-foot"><span>${money(p.saved)} saved</span><span class="pill">${esc(p.priority)}</span></div></article>`).join('')}</div>`;document.getElementById('add-product').onclick=()=>{const name=prompt('What are you saving for?');if(!name)return;const price=Number(prompt('How much will it cost?'));if(!price)return;data.products.push({id:Date.now(),name,category:'Personal goal',price,saved:0,icon:'✦',tone:'blue',priority:'Saving'});persistAction({action:'add-product',name,category:'Personal goal',price,saved:0,priority:'Saving'});render();toast('Goal added to your list')};document.querySelectorAll('.product-remove').forEach(b=>b.onclick=()=>{const removed=data.products.find(p=>p.id==b.dataset.id);data.products=data.products.filter(p=>p.id!=b.dataset.id);if(removed&&removed.id.toString().match(/^[0-9a-f-]{36}$/i))persistAction({action:'delete-product',id:removed.id});render();toast('Goal removed')})}
function renderNetworth(){const {assets,liabilities,net}=metrics();view.innerHTML=`<div class="grid networth-grid"><article class="card networth-hero"><div class="metric-label">Your net worth <span class="info-dot" title="Assets minus liabilities">i</span></div><div class="metric-value">${money(net)}</div><div class="metric-foot"><span class="metric-trend">↗ 3.6%</span> from last month</div></article><article class="card networth-breakdown"><h2 class="card-title">The full picture</h2><div class="breakdown-row"><span>Total assets</span><strong>${money(assets)}</strong></div><div class="breakdown-row"><span>Total liabilities</span><strong>− ${money(liabilities)}</strong></div><div class="breakdown-row"><span>Accounts tracked</span><strong>${data.accounts.length}</strong></div></article></div><div class="subhead"><div><h2>Your accounts</h2><p>Balances are entered by you and stay private to your account.</p></div><button class="button button-primary" id="add-account">+ Add account</button></div><div class="card table-card"><div class="table-wrap"><table class="full-table"><thead><tr><th>ACCOUNT</th><th>TYPE</th><th>BALANCE</th><th>INCLUDED IN NET WORTH</th><th></th></tr></thead><tbody>${data.accounts.map((a,i)=>`<tr><td><span class="account-icon">${a.icon}</span>${esc(a.name)}</td><td>${esc(a.type)}</td><td class="tx-amount ${a.balance>=0?'positive':''}">${a.balance<0?'−':''}${money(Math.abs(a.balance))}</td><td><span class="status">Included</span></td><td><button class="head-link edit-account" data-i="${i}">Edit balance</button></td></tr>`).join('')}</tbody></table></div></div><div class="page-section card" style="padding:14px 17px;color:#8a97aa;font-size:9px;line-height:1.55"><strong style="color:#5f6f86">You’re in control.</strong> BlueLedger never connects to your bank. Enter balances yourself to keep your financial picture private and up to date.</div>`;document.getElementById('add-account').onclick=()=>{const name=prompt('Account name?');if(!name)return;const type=prompt('Account type? (Bank account, Savings, Cash, Credit card)')||'Bank account';const balance=Number(prompt('Current balance? (Use a minus sign for debt)'));if(!Number.isFinite(balance))return;data.accounts.push({name,type,balance,icon:'▤'});persistAction({action:'add-account',name,type,balance,currency:data.currency});render();toast('Account added')};document.querySelectorAll('.edit-account').forEach(b=>b.onclick=()=>{const a=data.accounts[Number(b.dataset.i)],v=Number(prompt(`Enter the current balance for ${a.name}:`,a.balance));if(Number.isFinite(v)){a.balance=v;if(a.id)persistAction({action:'update-account',id:a.id,balance:v});render();toast('Balance updated')}})}
function renderActivity(){if(backendUser?.role==='admin'){view.innerHTML='<div class="card empty-state"><strong>Loading account activity…</strong></div>';api('/api/admin').then(({users,events,stats})=>{view.innerHTML='<div class="grid access-summary"><article class="card access-stat"><span>Registered accounts</span><strong>'+stats.users+'</strong></article><article class="card access-stat"><span>Active sessions</span><strong>'+stats.active_sessions+'</strong></article><article class="card access-stat"><span>Events · 30 days</span><strong>'+stats.events_30d+'</strong></article></div><div class="card table-card"><div class="card-head"><div><h2 class="card-title">Recent access & account activity</h2><p class="card-hint">Server recorded events · visible to admins only</p></div></div><div class="table-wrap"><table class="full-table"><thead><tr><th>ACCOUNT</th><th>ACTIVITY</th><th>DEVICE</th><th>IP ADDRESS</th><th>WHEN</th><th>STATUS</th></tr></thead><tbody>'+events.map(e=>'<tr><td>'+esc(e.email)+'</td><td>'+esc(e.action)+'</td><td>'+esc(e.device)+'</td><td>'+esc(e.ip_address||'—')+'</td><td>'+new Date(e.created_at).toLocaleString()+'</td><td><span class="status">'+(e.success?'Success':'Failed')+'</span></td></tr>').join('')+'</tbody></table></div></div><div class="page-section card table-card"><div class="card-head"><div><h2 class="card-title">Accounts</h2><p class="card-hint">Admin view shows basic account status only.</p></div></div><div class="table-wrap"><table class="full-table"><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>CREATED</th><th>LAST ACTIVE</th></tr></thead><tbody>'+users.map(u=>'<tr><td>'+esc(u.name)+'</td><td>'+esc(u.email)+'</td><td><span class="pill">'+esc(u.role)+'</span></td><td>'+new Date(u.created_at).toLocaleDateString()+'</td><td>'+(u.last_seen_at?new Date(u.last_seen_at).toLocaleString():'—')+'</td></tr>').join('')+'</tbody></table></div></div>'}).catch(e=>{view.innerHTML='<div class="card empty-state"><strong>Could not load access activity</strong><p>'+esc(e.message)+'</p></div>'});return}view.innerHTML=`<div class="grid access-summary"><article class="card access-stat"><span>Sign-ins this month</span><strong>12</strong></article><article class="card access-stat"><span>Active sessions</span><strong>1</strong></article><article class="card access-stat"><span>Last login</span><strong style="font-size:14px">Just now</strong></article></div><div class="card table-card"><div class="card-head"><div><h2 class="card-title">Recent access & account activity</h2><p class="card-hint">Only the account owner can see this log.</p></div><button class="button" id="clear-activity">Clear local log</button></div><div class="table-wrap"><table class="full-table"><thead><tr><th>USER</th><th>ACTIVITY</th><th>DEVICE</th><th>LOCATION</th><th>WHEN</th><th>STATUS</th></tr></thead><tbody>${data.events.map(e=>`<tr><td><span class="event-icon">${e.action.includes('Sign')?'↗':'◎'}</span>${esc(e.name)}<div style="font-size:8px;color:#a0aabb;margin:3px 0 0 38px">${esc(e.email)}</div></td><td>${esc(e.action)}</td><td>${esc(e.device)}</td><td>${esc(e.location)}</td><td>${esc(e.time)}</td><td><span class="status">${esc(e.status)}</span></td></tr>`).join('')}</tbody></table></div></div><div class="page-section card" style="padding:15px 18px"><div style="display:flex;gap:10px;align-items:flex-start"><span class="category-badge">🔒</span><div><strong style="font:700 10px Manrope">Privacy-first by design</strong><p style="margin:5px 0 0;font-size:9px;color:#909cad;line-height:1.55">Your activity log is scoped to your account. Bank passwords are never requested or stored. Connect a persistent database and authentication provider before inviting other users.</p></div></div></div>`;document.getElementById('clear-activity').onclick=()=>{data.events=[];render();toast('Local activity log cleared')}}
function renderSettings(){view.innerHTML=`<div class="grid settings-grid"><article class="card setting-card"><h3>Preferences</h3><p>Choose how your money is displayed.</p><div class="setting-line"><span>Display currency</span><select id="currency-select" class="filter-chip"><option value="PHP">PHP · Philippine peso (₱)</option><option value="USD">USD · US dollar ($)</option><option value="EUR">EUR · Euro (€)</option><option value="GBP">GBP · Pound (£)</option></select></div><div class="setting-line"><span>Month starts on</span><select class="filter-chip"><option>1st of each month</option><option>Payday</option></select></div></article><article class="card setting-card"><h3>Privacy & access</h3><p>Review the protections around your finances.</p><div class="setting-line"><span>Ask before exporting data</span><button class="toggle on" aria-label="Toggle export confirmation"></button></div><div class="setting-line"><span>Show access activity</span><button class="toggle on" aria-label="Toggle access activity"></button></div><div class="setting-line"><span>Automatic bank connection</span><span class="pill">Not connected</span></div></article><article class="card setting-card"><h3>Your account</h3><p>Personal finance workspace · demo profile</p><div class="setting-line"><span>Account owner</span><strong>Jamie Doe</strong></div><div class="setting-line"><span>Data storage</span><span class="pill">This browser</span></div></article><article class="card setting-card"><h3>About BlueLedger</h3><p>A calmer way to see where your money goes and what it can do for you.</p><div class="setting-line"><span>Version</span><strong>0.1.0 preview</strong></div><div class="setting-line"><span>Bank connections</span><strong>Manual entry only</strong></div></article></div>`;document.getElementById('currency-select').value=data.currency;document.getElementById('currency-select').onchange=e=>{data.currency=e.target.value;render();toast('Currency updated')};document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>b.classList.toggle('on'))}
function bindPageButtons(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page))}
function openModal(){document.getElementById('modal-backdrop').classList.add('open');document.getElementById('modal-backdrop').setAttribute('aria-hidden','false');document.querySelector('#transaction-form [name=date]').value=isoToday;document.querySelector('#transaction-form [name=description]').focus()}
function closeModal(){document.getElementById('modal-backdrop').classList.remove('open');document.getElementById('modal-backdrop').setAttribute('aria-hidden','true')}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show','success');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show','success'),2400)}
function exportCsv(){const rows=[['Description','Category','Amount','Type','Date','Account'],...data.transactions.map(t=>[t.description,t.category,t.amount,t.type,t.date,t.account])];const csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='blueledger-transactions.csv';a.click();URL.revokeObjectURL(a.href);toast('Your CSV is ready')}
function setTodayLabel(){const formatted=today.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}).toUpperCase();document.getElementById('today-label').textContent=formatted}

document.querySelectorAll('.nav-item[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
document.getElementById('add-transaction').onclick=openModal;
document.getElementById('modal-close').onclick=closeModal;
document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
document.querySelectorAll('.type-option').forEach(b=>b.onclick=()=>{transactionType=b.dataset.type;document.querySelectorAll('.type-option').forEach(x=>x.classList.toggle('selected',x===b));document.getElementById('modal-title').textContent=transactionType==='income'?'Add income':'Add an expense'});
document.getElementById('transaction-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const amount=Number(f.get('amount'));if(!amount||amount<=0)return;const tx={id:Date.now(),description:f.get('description').trim(),category:f.get('category'),amount,date:f.get('date'),account:f.get('account'),note:f.get('note').trim(),type:transactionType};data.transactions.unshift(tx);persistAction({action:'add-transaction',...tx});const bud=data.budgets.find(b=>b.name===tx.category);if(bud&&tx.type==='expense')bud.spent+=amount;data.events.unshift({name:'Jamie Doe',email:'jamie@example.com',action:'Added transaction',device:'This browser',location:'This device',time:'Just now',status:'Success'});closeModal();e.target.reset();transactionType='expense';document.querySelectorAll('.type-option').forEach(x=>x.classList.toggle('selected',x.dataset.type==='expense'));document.getElementById('modal-title').textContent='Add a transaction';render();toast('Transaction saved')};
document.getElementById('export-btn').onclick=exportCsv;
document.getElementById('mobile-menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
document.getElementById('search-open').onclick=showSearch;document.getElementById('search-wide').onclick=showSearch;
let authMode='login';
function openAuth(mode='login'){authMode=mode;const back=document.getElementById('auth-backdrop'),card=back.querySelector('.auth-modal');card.classList.toggle('signup',mode==='register');document.getElementById('auth-title').textContent=mode==='register'?'Create your account':'Sign in to BlueLedger';document.getElementById('auth-submit').innerHTML=(mode==='register'?'Create account':'Sign in')+' <span>→</span>';document.getElementById('auth-switch').textContent=mode==='register'?'Already have an account? Sign in':'Create a new account';document.getElementById('auth-error').textContent='';back.classList.add('open');back.setAttribute('aria-hidden','false')}
function closeAuth(){const back=document.getElementById('auth-backdrop');back.classList.remove('open');back.setAttribute('aria-hidden','true')}
document.getElementById('account-button').onclick=()=>backendUser?api('/api/auth',{method:'POST',body:JSON.stringify({action:'logout'})}).then(()=>location.reload()).catch(()=>toast('Could not sign out')):openAuth();
document.getElementById('sync-signin').onclick=()=>openAuth();document.getElementById('auth-close').onclick=closeAuth;document.getElementById('auth-backdrop').addEventListener('click',e=>{if(e.target.id==='auth-backdrop')closeAuth()});document.getElementById('auth-switch').onclick=()=>openAuth(authMode==='login'?'register':'login');
document.getElementById('auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),error=document.getElementById('auth-error');error.textContent='';try{const result=await api('/api/auth',{method:'POST',body:JSON.stringify({action:authMode,email:f.get('email'),password:f.get('password'),name:f.get('name')})});backendUser=result.user;closeAuth();await refreshBackend();toast('You’re signed in securely')}catch(err){error.textContent=err.message}};
function showSearch(){const overlay=document.createElement('div');overlay.className='search-overlay';overlay.innerHTML='<div class="search-box"><input placeholder="Search transactions, budgets, products…" autofocus /><div class="search-results"><button data-go="transactions">↔ &nbsp; Transactions</button><button data-go="budgets">◷ &nbsp; Budgets</button><button data-go="products">▦ &nbsp; Product list</button><button data-go="networth">◈ &nbsp; Net worth</button></div></div>';overlay.onclick=e=>{if(e.target===overlay)overlay.remove();if(e.target.dataset.go){setPage(e.target.dataset.go);overlay.remove()}};document.body.append(overlay);overlay.querySelector('input').focus();overlay.querySelector('input').oninput=e=>{const q=e.target.value.toLowerCase();overlay.querySelectorAll('.search-results button').forEach(b=>b.style.display=b.textContent.toLowerCase().includes(q)?'':'none')}}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'){closeModal();document.querySelector('.search-overlay')?.remove()}});
setTodayLabel();setPage('dashboard');refreshBackend();

if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))}
